import React, { useState } from 'react';
import { API } from './config';

function UserPanel({ setUserToken, userToken }) {
  const [form, setForm] = useState({});
  const [myChallans, setMyChallans] = useState([]);

  async function signup(e) {
    e.preventDefault();
    const res = await fetch(API + '/user/signup', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(form)
    });
    const data = await res.json();
    alert(data.message || 'Signup successful');
  }

  async function login(e) {
    e.preventDefault();
    const res = await fetch(API + '/user/login', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email: form.email, password: form.password })
    });
    const data = await res.json();
    if (data.token) {
      setUserToken(data.token);
      localStorage.setItem('uid', data.userId);
      alert('Logged in');
      fetchMine(data.userId);
    } else {
      alert(data.message || 'Error');
    }
  }

  async function fetchMine(userId) {
    const id = userId || localStorage.getItem('uid');
    if (!id) return alert('No user id');
    const res = await fetch(API + '/challan/user/' + id);
    const data = await res.json();
    setMyChallans(data);
  }

  async function pay(challanId) {
    const res = await fetch(API + '/challan/pay/' + challanId, { method: 'POST' });
    const data = await res.json();
    alert(data.message || 'Paid');
    fetchMine();
  }

  return (
    <div style={{ fontFamily: 'Arial, sans-serif', padding: '20px' }}>
      <h2 style={{ textAlign: 'center', marginBottom: '20px', color: '#333' }}>User Panel</h2>

      {/* Forms Section */}
      <div style={{ display: 'flex', gap: '40px', justifyContent: 'center', marginBottom: '30px' }}>
        {/* Signup Form */}
        <form
          onSubmit={signup}
          style={{
            background: '#f9f9f9',
            padding: '20px',
            borderRadius: '8px',
            boxShadow: '0 2px 6px rgba(0,0,0,0.1)',
            width: '250px'
          }}
        >
          <h4 style={{ marginBottom: '10px', color: '#444' }}>Signup</h4>
          <input
            placeholder="Name"
            onChange={e => setForm({ ...form, name: e.target.value })}
            style={inputStyle}
          />
          <input
            placeholder="Email"
            onChange={e => setForm({ ...form, email: e.target.value })}
            style={inputStyle}
          />
          <input
            placeholder="Vehicle Number"
            onChange={e => setForm({ ...form, vehicleNumber: e.target.value })}
            style={inputStyle}
          />
          <input
            type="password"
            placeholder="Password"
            onChange={e => setForm({ ...form, password: e.target.value })}
            style={inputStyle}
          />
          <button style={buttonStyle}>Signup</button>
        </form>

        {/* Login Form */}
        <form
          onSubmit={login}
          style={{
            background: '#f9f9f9',
            padding: '20px',
            borderRadius: '8px',
            boxShadow: '0 2px 6px rgba(0,0,0,0.1)',
            width: '250px'
          }}
        >
          <h4 style={{ marginBottom: '10px', color: '#444' }}>Login</h4>
          <input
            placeholder="Email"
            onChange={e => setForm({ ...form, email: e.target.value })}
            style={inputStyle}
          />
          <input
            type="password"
            placeholder="Password"
            onChange={e => setForm({ ...form, password: e.target.value })}
            style={inputStyle}
          />
          <button style={buttonStyle}>Login</button>
        </form>
      </div>

      {/* Challans Table */}
      <div>
        <h3 style={{ marginBottom: '10px', color: '#333' }}>My Challans</h3>
        <button onClick={() => fetchMine()} style={{ ...buttonStyle, marginBottom: '15px' }}>
          Refresh
        </button>
        <table style={tableStyle}>
          <thead>
            <tr>
              <th>#</th>
              <th>Vehicle</th>
              <th>Cause</th>
              <th>Fine</th>
              <th>Status</th>
              <th>Action</th>
            </tr>
          </thead>
          <tbody>
            {myChallans.map((c, i) => (
              <tr key={c._id}>
                <td>{i + 1}</td>
                <td>{c.vehicleNumber}</td>
                <td>{c.cause}</td>
                <td>{c.fine}</td>
                <td>{c.status}</td>
                <td>
                  {c.status !== 'Paid' && (
                    <button onClick={() => pay(c._id)} style={buttonStyle}>
                      Pay
                    </button>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

// 🔹 Shared Styles
const inputStyle = {
  display: 'block',
  width: '100%',
  padding: '8px',
  marginBottom: '10px',
  border: '1px solid #ccc',
  borderRadius: '4px'
};

const buttonStyle = {
  background: '#007bff',
  color: '#fff',
  border: 'none',
  padding: '8px 12px',
  borderRadius: '4px',
  cursor: 'pointer'
};

const tableStyle = {
  width: '100%',
  borderCollapse: 'collapse',
  boxShadow: '0 2px 6px rgba(0,0,0,0.1)'
};

export default UserPanel;
